    buildVsBuyWhy: "Partner-led. The bank has real digital capability and a modernisation agenda but executes with vendors and integrators. Its efficiency-led culture makes it a demanding buyer that will require a hard business case, not a technology narrative.",
    whyNotBuild: "Its digital investment targets customer-facing propositions and channel experience, where it competes. Speech across three languages, telephony and WhatsApp orchestration, collections policy encoding and per-conversation evaluation are infrastructure that would consume the same budget without producing a customer-visible differentiator.",
    workflows: [
      { name: "Hire-purchase payment reminders and early-bucket collections", friction: "Reminder and early collections calling is capacity-bound during office hours, so a share of the auto book receives only messaging, and arrangements vary by collector and vendor.", outcome: "Full pre-due and early-bucket coverage in three languages with consistent approved arrangements, in-channel payment and complete conduct evidence.", channels: ["Voice", "WhatsApp", "SMS"], systems: ["Hire-purchase and financing servicing systems", "Collections case management", "Payment and DuitNow rails", "Approved restructuring matrix"], value: 3, complexity: 2 },
      { name: "Card and everyday banking servicing", friction: "Statement, transaction-dispute, limit and card-activation queries arrive in three languages and consume contact-centre capacity at a cost per contact that is hard to justify on small-balance accounts.", outcome: "Routine servicing completed inside the conversation in the customer's language, with disputes and fraud cases escalated to specialists with full context.", channels: ["Voice", "WhatsApp", "App chat"], systems: ["Card management system", "Core banking", "Dispute and fraud case management", "Authentication and OTP service"], value: 2, complexity: 2 },
      { name: "Mortgage and financing application status support", friction: "Applicants and property agents chase mortgage application progress and document requirements by phone and email, and each enquiry requires a human to check the origination workflow.", outcome: "Grounded application-status and document-requirement answers at any hour, with proactive milestone updates that stop the status calls entirely.", channels: ["WhatsApp", "Voice", "Email"], systems: ["Loan origination and credit workflow", "Document management", "Valuation and legal coordination records", "CRM"], value: 2, complexity: 2 },
    ],
    existing: { has: ["Hong Leong Connect digital banking and mobile app for retail customers", "Multilingual contact centre serving Bahasa Malaysia, English and Mandarin", "WhatsApp and messaging channels used for customer servicing", "National branch network plus dedicated SME and priority banking centres"], gaps: ["Payment arrangements cannot be negotiated and concluded in an inbound conversation", "Mortgage application status requires human lookup rather than proactive updates", "Contact-centre language coverage varies by shift rather than being uniform", "Collections conduct evidence relies on sampled QA rather than full-coverage evaluation"] },
    risks: ["Bank Negara Malaysia fair-treatment and fair-debt-collection expectations govern collections conduct, disclosure and restructuring or AKPK referral obligations.", "Malaysia's Personal Data Protection Act 2010 governs consent for outbound contact and retention of voice and messaging records.", "Shariah governance applies to Hong Leong Islamic financing products, requiring compliant terminology and approved offer structures."],
    economics: { volumeMonthly: 1000000, costPerInteraction: 2.0, automationRate: 0.55, basis: "Seller assumptions for an established Malaysian retail and SME bank serving three languages at local cost levels; validate against Hong Leong Bank's actual contact volumes, language mix and cost per contact." },
    pilotScope: "A three-language hire-purchase reminder and early-bucket collections agent on voice and WhatsApp, integrated to financing servicing and payment rails, measured on contact coverage, promise-kept rate and cost per resolved account against a control portfolio.",
