    existing: { has: ["National branch network serving members across urban and small-town Malaysia", "Bank Rakyat mobile banking and online channels for account servicing", "Bahasa Malaysia contact centre handling financing and account enquiries", "WhatsApp and messaging channels used for customer notifications and support"], gaps: ["Members cannot obtain settlement figures or restructuring eligibility without a human", "Deduction failures are discovered by the member rather than flagged proactively by the bank", "Branch queues are consumed by information requests rather than transactions", "No evidence trail demonstrating consistent conduct across every collections conversation"] },
    risks: ["Shariah governance requires approved terminology and financing structures in every customer conversation, with auditability of content.", "Bank Negara Malaysia fair-treatment and fair-debt-collection expectations apply to member financing conduct including hardship handling.", "Malaysia's Personal Data Protection Act 2010 governs member and employer payroll data and the retention of voice and messaging records."],
    economics: { volumeMonthly: 1200000, costPerInteraction: 1.5, automationRate: 0.6, basis: "Seller assumptions for Malaysia's largest Islamic cooperative bank with a very large salary-deduction financing base; validate against Bank Rakyat's actual contact-centre and branch enquiry volumes and cost per contact." },
    pilotScope: "A Bahasa Malaysia financing-status and settlement-figure agent on voice and WhatsApp, grounded in the Islamic financing servicing system with Shariah-approved language, measured on hotline deflection, branch enquiry reduction and first-contact resolution.",
